# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Tuple, List, Iterable, Dict

from hourglass.models import Shift

Totals = Dict[str, Tuple[int, int]]

def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")

def _tally(shifts: List[Shift]) -> Totals:
    totals = {}
    for shift in shifts:
        n, m = totals.get(shift.worker, (0, 0))
        m += shift.span.minutes
        totals[shift.worker] = (n + 1, m)
    return totals

def _busiest(item: Tuple[str, Tuple[int, int]]) -> tuple:
    return (-item[1][1], item[0])

def _row(name: str, count: int, minutes: int) -> str:
    word = "shift" if count == 1 else "shifts"
    hours = f"{minutes / 60:.1f}"
    return f"{name}: {count} {word}, {hours} hours"

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    shifts = list(shifts)
    _check(shifts)
    rows = sorted(_tally(shifts).items(), key=_busiest)
    return [_row(name, *data) for name, data in rows]
